                teacher: '"보기를 고르면 그다음에 어떻게 되는지 보여요." 알아들은 척하는 보기(OK!)를 고른 학생에게 결과 화면을 함께 읽고 "알아들은 척하면 대화는 끝나도 일은 꼬여요."라고 말한다. 크게 말해 달라는 보기를 고른 학생에게는 "소리는 잘 들렸다고 했지요? 무엇을 몰랐나요?"라고 묻는다. 마지막 짝 활동은 한 사람이 일부러 빠르게 말하거나 어려운 낱말을 넣고, 다른 사람이 되묻는다.',
