                    toolOptions: { cards: [{ id: 'a', text: 'You use it on rainy days.' }, { id: 'b', text: 'You hold it over your head.' }, { id: 'c', text: 'It keeps you dry.' }, { id: 'd', text: 'You wear it on your feet.', why: '발에 신는 것은 장화나 신발이에요. 우산이 아니에요.' }] },
