                    toolOptions: { cards: [{ id: 'a', text: 'Last Friday, I went to the science museum.' }, { id: 'b', text: 'I saw many robots.' }, { id: 'c', text: 'I see many robots.', why: '메모와는 맞지만 see는 지금 꼴이에요. saw로 써요.' }, { id: 'd', text: 'I went to the zoo.', why: '지난 꼴이지만 메모의 곳은 과학관이에요.' }] },
